// binary search for constructor in sorted index
fn lookup_ctor(id: u32) -> Option<(usize, usize)> {
    CTOR_INDEX.binary_search_by_key(&id, |e| e.0)
        .ok()
        .map(|i| (CTOR_INDEX[i].1 as usize, CTOR_INDEX[i].2 as usize))
}

// skip a boxed TL object by reading its constructor and interpreting field descriptors
pub fn skip_tl(cursor: &mut Cursor<&[u8]>) -> Result<(), String> {
    let ctor = cursor.read_u32::<LittleEndian>().map_err(|e| format!("skip_tl: read ctor: {e}"))?;
    skip_tl_by_id(cursor, ctor)
}

pub fn skip_tl_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<(), String> {
    let (offset, count) = match lookup_ctor(ctor) {
        Some(v) => v,
        None => return Err(format!("skip_tl: unknown ctor {:#010x}", ctor)),
    };
    let fields = &FIELD_DATA[offset..offset + count];
    let mut flag_vals: [u32; 3] = [0; 3]; // flags, flags2, flags3
    let mut flags_seen: usize = 0;
    for &encoded in fields {
        let ft = encoded & 0xf;
        let conditional = (encoded >> 15) & 1 != 0;
        if conditional {
            let ffi = ((encoded >> 9) & 0x3) as usize;
            let bit = ((encoded >> 4) & 0x1f) as u32;
            if flag_vals[ffi] & (1 << bit) == 0 {
                continue; // field not present
            }
        }
        match ft {
            0 => { cursor.read_i32::<LittleEndian>().map_err(|_| "skip int")?; } // int
            1 => { cursor.read_i64::<LittleEndian>().map_err(|_| "skip long")?; } // long
            2 => { cursor.read_i64::<LittleEndian>().map_err(|_| "skip double")?; } // double
            3 | 4 => { deserialize_bytes(cursor).map_err(|_| "skip str/bytes".to_string())?; } // str/bytes
            5 => { skip_tl(cursor)?; } // nested object
            6 => { // flags field — read and store in next slot
                let v = cursor.read_u32::<LittleEndian>().map_err(|_| "skip flags")?;
                if flags_seen < 3 { flag_vals[flags_seen] = v; }
                flags_seen += 1;
            }
            7 => { cursor.read_u32::<LittleEndian>().map_err(|_| "skip Bool")?; } // boxed Bool
            8 => { // Vector<int>
                cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
                let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec count")?;
                for _ in 0..cnt { cursor.read_i32::<LittleEndian>().map_err(|_| "vec int")?; }
            }
            9 => { // Vector<long>
                cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
                let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec count")?;
                for _ in 0..cnt { cursor.read_i64::<LittleEndian>().map_err(|_| "vec long")?; }
            }
            10 | 11 => { // Vector<string> / Vector<bytes>
                cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
                let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec count")?;
                for _ in 0..cnt { deserialize_bytes(cursor).map_err(|_| "vec str".to_string())?; }
            }
            12 => { // Vector<Object>
                cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
                let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec count")?;
                for _ in 0..cnt { skip_tl(cursor)?; }
            }
            13 => { // int128
                let mut b = [0u8; 16]; cursor.read_exact(&mut b).map_err(|_| "skip int128")?;
            }
            14 => { // int256
                let mut b = [0u8; 32]; cursor.read_exact(&mut b).map_err(|_| "skip int256")?;
            }
            15 => { } // true — no wire data
            _ => {}
        }
    }
    Ok(())
}

// --- method serializers ---
use byteorder::WriteBytesExt;
use super::tl::{serialize_string, serialize_bytes as tl_serialize_bytes};

pub fn build_true() -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x3fedd339).unwrap();
    buf
}

pub fn build_boolFalse() -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xbc799737).unwrap();
    buf
}

pub fn build_boolTrue() -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x997275b5).unwrap();
    buf
}

pub fn build_vector() -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf
}

pub fn build_error(code: i32, text: &str) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xc4b9f9bb).unwrap();
    buf.write_i32::<LittleEndian>(code).unwrap();
    buf.extend(serialize_string(text));
    buf
}

pub fn build_ipPort(ipv4: i32, port: i32) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xd433ad73).unwrap();
    buf.write_i32::<LittleEndian>(ipv4).unwrap();
    buf.write_i32::<LittleEndian>(port).unwrap();
    buf
}

pub fn build_ipPortSecret(ipv4: i32, port: i32, secret: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x37982646).unwrap();
    buf.write_i32::<LittleEndian>(ipv4).unwrap();
    buf.write_i32::<LittleEndian>(port).unwrap();
    buf.extend(tl_serialize_bytes(secret));
    buf
}

pub fn build_accessPointRule(phone_prefix_rules: &str, dc_id: i32, ips: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x4679b65f).unwrap();
    buf.extend(serialize_string(phone_prefix_rules));
    buf.write_i32::<LittleEndian>(dc_id).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(ips.len() as u32).unwrap();
    for item in ips { buf.extend_from_slice(item); }
    buf
}

pub fn build_help_configSimple(date: i32, expires: i32, rules: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x5a592a6c).unwrap();
    buf.write_i32::<LittleEndian>(date).unwrap();
    buf.write_i32::<LittleEndian>(expires).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(rules.len() as u32).unwrap();
    for item in rules { buf.extend_from_slice(item); }
    buf
}

pub fn build_inputPeerPhotoFileLocationLegacy(big: bool, peer: &[u8], volume_id: i64, local_id: i32) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x27d69997).unwrap();
    let flags_val: u32 = (if big { 1u32 << 0 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(peer);
    buf.write_i64::<LittleEndian>(volume_id).unwrap();
    buf.write_i32::<LittleEndian>(local_id).unwrap();
    buf
}

pub fn build_inputStickerSetThumbLegacy(stickerset: &[u8], volume_id: i64, local_id: i32) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x0dbaeae9).unwrap();
    buf.extend_from_slice(stickerset);
    buf.write_i64::<LittleEndian>(volume_id).unwrap();
    buf.write_i32::<LittleEndian>(local_id).unwrap();
    buf
}

pub fn build_invokeAfterMsg(msg_id: i64, query: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xcb9f372d).unwrap();
    buf.write_i64::<LittleEndian>(msg_id).unwrap();
    buf.extend_from_slice(query);
    buf
}

pub fn build_invokeAfterMsgs(msg_ids: &[i64], query: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x3dc4b4f0).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(msg_ids.len() as u32).unwrap();
    for &item in msg_ids { buf.write_i64::<LittleEndian>(item).unwrap(); }
    buf.extend_from_slice(query);
    buf
}

pub fn build_initConnection(api_id: i32, device_model: &str, system_version: &str, app_version: &str, system_lang_code: &str, lang_pack: &str, lang_code: &str, proxy: Option<&[u8]>, params: Option<&[u8]>, query: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xc1cd5ea9).unwrap();
    let flags_val: u32 = (if proxy.is_some() { 1u32 << 0 } else { 0 }) | (if params.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i32::<LittleEndian>(api_id).unwrap();
    buf.extend(serialize_string(device_model));
    buf.extend(serialize_string(system_version));
    buf.extend(serialize_string(app_version));
    buf.extend(serialize_string(system_lang_code));
    buf.extend(serialize_string(lang_pack));
    buf.extend(serialize_string(lang_code));
    if let Some(v) = proxy {
        buf.extend_from_slice(v);
    }
    if let Some(v) = params {
        buf.extend_from_slice(v);
    }
    buf.extend_from_slice(query);
    buf
}

pub fn build_invokeWithLayer(layer: i32, query: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xda9b0d0d).unwrap();
    buf.write_i32::<LittleEndian>(layer).unwrap();
    buf.extend_from_slice(query);
    buf
}

