pub fn build_account_createTheme(slug: &str, title: &str, document: Option<&[u8]>, settings: Option<&[&[u8]]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x652e4400).unwrap();
    let flags_val: u32 = (if document.is_some() { 1u32 << 2 } else { 0 }) | (if settings.is_some() { 1u32 << 3 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend(serialize_string(slug));
    buf.extend(serialize_string(title));
    if let Some(v) = document {
        buf.extend_from_slice(v);
    }
    if let Some(v) = settings {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf
}

pub fn build_account_updateTheme(format: &str, theme: &[u8], slug: Option<&str>, title: Option<&str>, document: Option<&[u8]>, settings: Option<&[&[u8]]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x2bf40ccc).unwrap();
    let flags_val: u32 = (if slug.is_some() { 1u32 << 0 } else { 0 }) | (if title.is_some() { 1u32 << 1 } else { 0 }) | (if document.is_some() { 1u32 << 2 } else { 0 }) | (if settings.is_some() { 1u32 << 3 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend(serialize_string(format));
    buf.extend_from_slice(theme);
    if let Some(v) = slug {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = title {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = document {
        buf.extend_from_slice(v);
    }
    if let Some(v) = settings {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf
}

