pub fn build_messages_sendMultiMedia(silent: bool, background: bool, clear_draft: bool, noforwards: bool, update_stickersets_order: bool, invert_media: bool, allow_paid_floodskip: bool, peer: &[u8], reply_to: Option<&[u8]>, multi_media: &[&[u8]], schedule_date: Option<i32>, send_as: Option<&[u8]>, quick_reply_shortcut: Option<&[u8]>, effect: Option<i64>, allow_paid_stars: Option<i64>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x1bf89d74).unwrap();
    let flags_val: u32 = (if silent { 1u32 << 5 } else { 0 }) | (if background { 1u32 << 6 } else { 0 }) | (if clear_draft { 1u32 << 7 } else { 0 }) | (if noforwards { 1u32 << 14 } else { 0 }) | (if update_stickersets_order { 1u32 << 15 } else { 0 }) | (if invert_media { 1u32 << 16 } else { 0 }) | (if allow_paid_floodskip { 1u32 << 19 } else { 0 }) | (if reply_to.is_some() { 1u32 << 0 } else { 0 }) | (if schedule_date.is_some() { 1u32 << 10 } else { 0 }) | (if send_as.is_some() { 1u32 << 13 } else { 0 }) | (if quick_reply_shortcut.is_some() { 1u32 << 17 } else { 0 }) | (if effect.is_some() { 1u32 << 18 } else { 0 }) | (if allow_paid_stars.is_some() { 1u32 << 21 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(peer);
    if let Some(v) = reply_to {
        buf.extend_from_slice(v);
    }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(multi_media.len() as u32).unwrap();
    for item in multi_media { buf.extend_from_slice(item); }
    if let Some(v) = schedule_date {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = send_as {
        buf.extend_from_slice(v);
    }
    if let Some(v) = quick_reply_shortcut {
        buf.extend_from_slice(v);
    }
    if let Some(v) = effect {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = allow_paid_stars {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    buf
}

