pub fn build_messages_requestWebView(from_bot_menu: bool, silent: bool, compact: bool, fullscreen: bool, peer: &[u8], bot: &[u8], url: Option<&str>, start_param: Option<&str>, theme_params: Option<&[u8]>, platform: &str, reply_to: Option<&[u8]>, send_as: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x269dc2c1).unwrap();
    let flags_val: u32 = (if from_bot_menu { 1u32 << 4 } else { 0 }) | (if silent { 1u32 << 5 } else { 0 }) | (if compact { 1u32 << 7 } else { 0 }) | (if fullscreen { 1u32 << 8 } else { 0 }) | (if url.is_some() { 1u32 << 1 } else { 0 }) | (if start_param.is_some() { 1u32 << 3 } else { 0 }) | (if theme_params.is_some() { 1u32 << 2 } else { 0 }) | (if reply_to.is_some() { 1u32 << 0 } else { 0 }) | (if send_as.is_some() { 1u32 << 13 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(peer);
    buf.extend_from_slice(bot);
    if let Some(v) = url {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = start_param {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = theme_params {
        buf.extend_from_slice(v);
    }
    buf.extend(serialize_string(platform));
    if let Some(v) = reply_to {
        buf.extend_from_slice(v);
    }
    if let Some(v) = send_as {
        buf.extend_from_slice(v);
    }
    buf
}

