pub fn build_photos_uploadProfilePhoto(fallback: bool, bot: Option<&[u8]>, file: Option<&[u8]>, video: Option<&[u8]>, video_start_ts: Option<f64>, video_emoji_markup: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x0388a3b5).unwrap();
    let flags_val: u32 = (if fallback { 1u32 << 3 } else { 0 }) | (if bot.is_some() { 1u32 << 5 } else { 0 }) | (if file.is_some() { 1u32 << 0 } else { 0 }) | (if video.is_some() { 1u32 << 1 } else { 0 }) | (if video_start_ts.is_some() { 1u32 << 2 } else { 0 }) | (if video_emoji_markup.is_some() { 1u32 << 4 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = bot {
        buf.extend_from_slice(v);
    }
    if let Some(v) = file {
        buf.extend_from_slice(v);
    }
    if let Some(v) = video {
        buf.extend_from_slice(v);
    }
    if let Some(v) = video_start_ts {
        buf.write_i64::<LittleEndian>(v.to_bits() as i64).unwrap();
    }
    if let Some(v) = video_emoji_markup {
        buf.extend_from_slice(v);
    }
    buf
}

