pub fn build_channels_createChannel(broadcast: bool, megagroup: bool, for_import: bool, forum: bool, title: &str, about: &str, geo_point: Option<&[u8]>, address: Option<&str>, ttl_period: Option<i32>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x91006707).unwrap();
    let flags_val: u32 = (if broadcast { 1u32 << 0 } else { 0 }) | (if megagroup { 1u32 << 1 } else { 0 }) | (if for_import { 1u32 << 3 } else { 0 }) | (if forum { 1u32 << 5 } else { 0 }) | (if geo_point.is_some() { 1u32 << 2 } else { 0 }) | (if address.is_some() { 1u32 << 2 } else { 0 }) | (if ttl_period.is_some() { 1u32 << 4 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend(serialize_string(title));
    buf.extend(serialize_string(about));
    if let Some(v) = geo_point {
        buf.extend_from_slice(v);
    }
    if let Some(v) = address {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = ttl_period {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    buf
}

