pub fn build_channels_getAdminLog(channel: &[u8], q: &str, events_filter: Option<&[u8]>, admins: Option<&[&[u8]]>, max_id: i64, min_id: i64, limit: i32) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x33ddf480).unwrap();
    let flags_val: u32 = (if events_filter.is_some() { 1u32 << 0 } else { 0 }) | (if admins.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(channel);
    buf.extend(serialize_string(q));
    if let Some(v) = events_filter {
        buf.extend_from_slice(v);
    }
    if let Some(v) = admins {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf.write_i64::<LittleEndian>(max_id).unwrap();
    buf.write_i64::<LittleEndian>(min_id).unwrap();
    buf.write_i32::<LittleEndian>(limit).unwrap();
    buf
}

