pub fn build_channels_searchPosts(hashtag: Option<&str>, query: Option<&str>, offset_rate: i32, offset_peer: &[u8], offset_id: i32, limit: i32, allow_paid_stars: Option<i64>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xf2c4f24d).unwrap();
    let flags_val: u32 = (if hashtag.is_some() { 1u32 << 0 } else { 0 }) | (if query.is_some() { 1u32 << 1 } else { 0 }) | (if allow_paid_stars.is_some() { 1u32 << 2 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = hashtag {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = query {
        buf.extend(serialize_string(v));
    }
    buf.write_i32::<LittleEndian>(offset_rate).unwrap();
    buf.extend_from_slice(offset_peer);
    buf.write_i32::<LittleEndian>(offset_id).unwrap();
    buf.write_i32::<LittleEndian>(limit).unwrap();
    if let Some(v) = allow_paid_stars {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    buf
}

