pub fn build_payments_getResaleStarGifts(sort_by_price: bool, sort_by_num: bool, for_craft: bool, stars_only: bool, attributes_hash: Option<i64>, gift_id: i64, attributes: Option<&[&[u8]]>, offset: &str, limit: i32) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x7a5fa236).unwrap();
    let flags_val: u32 = (if sort_by_price { 1u32 << 1 } else { 0 }) | (if sort_by_num { 1u32 << 2 } else { 0 }) | (if for_craft { 1u32 << 4 } else { 0 }) | (if stars_only { 1u32 << 5 } else { 0 }) | (if attributes_hash.is_some() { 1u32 << 0 } else { 0 }) | (if attributes.is_some() { 1u32 << 3 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = attributes_hash {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    buf.write_i64::<LittleEndian>(gift_id).unwrap();
    if let Some(v) = attributes {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf.extend(serialize_string(offset));
    buf.write_i32::<LittleEndian>(limit).unwrap();
    buf
}

