pub fn build_payments_updateStarGiftCollection(peer: &[u8], collection_id: i32, title: Option<&str>, delete_stargift: Option<&[&[u8]]>, add_stargift: Option<&[&[u8]]>, order: Option<&[&[u8]]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x4fddbee7).unwrap();
    let flags_val: u32 = (if title.is_some() { 1u32 << 0 } else { 0 }) | (if delete_stargift.is_some() { 1u32 << 1 } else { 0 }) | (if add_stargift.is_some() { 1u32 << 2 } else { 0 }) | (if order.is_some() { 1u32 << 3 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(peer);
    buf.write_i32::<LittleEndian>(collection_id).unwrap();
    if let Some(v) = title {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = delete_stargift {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = add_stargift {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = order {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf
}

