    let flags_val: u32 = (if muted.is_some() { 1u32 << 0 } else { 0 }) | (if volume.is_some() { 1u32 << 1 } else { 0 }) | (if raise_hand.is_some() { 1u32 << 2 } else { 0 }) | (if video_stopped.is_some() { 1u32 << 3 } else { 0 }) | (if video_paused.is_some() { 1u32 << 4 } else { 0 }) | (if presentation_paused.is_some() { 1u32 << 5 } else { 0 });
