pub fn build_stories_updateAlbum(peer: &[u8], album_id: i32, title: Option<&str>, delete_stories: Option<&[i32]>, add_stories: Option<&[i32]>, order: Option<&[i32]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x5e5259b6).unwrap();
    let flags_val: u32 = (if title.is_some() { 1u32 << 0 } else { 0 }) | (if delete_stories.is_some() { 1u32 << 1 } else { 0 }) | (if add_stories.is_some() { 1u32 << 2 } else { 0 }) | (if order.is_some() { 1u32 << 3 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(peer);
    buf.write_i32::<LittleEndian>(album_id).unwrap();
    if let Some(v) = title {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = delete_stories {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for &item in v { buf.write_i32::<LittleEndian>(item).unwrap(); }
    }
    if let Some(v) = add_stories {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for &item in v { buf.write_i32::<LittleEndian>(item).unwrap(); }
    }
    if let Some(v) = order {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for &item in v { buf.write_i32::<LittleEndian>(item).unwrap(); }
    }
    buf
}

