pub fn build_stories_startLive(pinned: bool, noforwards: bool, rtmp_stream: bool, peer: &[u8], caption: Option<&str>, entities: Option<&[&[u8]]>, privacy_rules: &[&[u8]], random_id: i64, messages_enabled: Option<bool>, send_paid_messages_stars: Option<i64>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xd069ccde).unwrap();
    let flags_val: u32 = (if pinned { 1u32 << 2 } else { 0 }) | (if noforwards { 1u32 << 4 } else { 0 }) | (if rtmp_stream { 1u32 << 5 } else { 0 }) | (if caption.is_some() { 1u32 << 0 } else { 0 }) | (if entities.is_some() { 1u32 << 1 } else { 0 }) | (if messages_enabled.is_some() { 1u32 << 6 } else { 0 }) | (if send_paid_messages_stars.is_some() { 1u32 << 7 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(peer);
    if let Some(v) = caption {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = entities {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(privacy_rules.len() as u32).unwrap();
    for item in privacy_rules { buf.extend_from_slice(item); }
    buf.write_i64::<LittleEndian>(random_id).unwrap();
    if let Some(v) = messages_enabled {
        buf.write_u32::<LittleEndian>(if v { 0x997275b5 } else { 0xbc799737 }).unwrap();
    }
    if let Some(v) = send_paid_messages_stars {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    buf
}

