pub fn serialize_inputPhoneContact(client_id: i64, phone: &str, first_name: &str, last_name: &str, note: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x6a1dc4be).unwrap();
    let flags_val: u32 = (if note.is_some() { 1u32 << 0 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i64::<LittleEndian>(client_id).unwrap();
    buf.extend(serialize_string(phone));
    buf.extend(serialize_string(first_name));
    buf.extend(serialize_string(last_name));
    if let Some(v) = note {
        buf.extend_from_slice(v);
    }
    buf
}

