pub fn serialize_inputMediaUploadedPhoto(spoiler: bool, live_photo: bool, file: &[u8], stickers: Option<&[&[u8]]>, ttl_seconds: Option<i32>, video: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x7d8375da).unwrap();
    let flags_val: u32 = (if spoiler { 1u32 << 2 } else { 0 }) | (if live_photo { 1u32 << 3 } else { 0 }) | (if stickers.is_some() { 1u32 << 0 } else { 0 }) | (if ttl_seconds.is_some() { 1u32 << 1 } else { 0 }) | (if video.is_some() { 1u32 << 3 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(file);
    if let Some(v) = stickers {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = ttl_seconds {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = video {
        buf.extend_from_slice(v);
    }
    buf
}

pub fn serialize_inputMediaPhoto(spoiler: bool, live_photo: bool, id: &[u8], ttl_seconds: Option<i32>, video: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xe3af4434).unwrap();
    let flags_val: u32 = (if spoiler { 1u32 << 1 } else { 0 }) | (if live_photo { 1u32 << 2 } else { 0 }) | (if ttl_seconds.is_some() { 1u32 << 0 } else { 0 }) | (if video.is_some() { 1u32 << 2 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(id);
    if let Some(v) = ttl_seconds {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = video {
        buf.extend_from_slice(v);
    }
    buf
}

