pub fn serialize_inputMediaUploadedDocument(nosound_video: bool, force_file: bool, spoiler: bool, file: &[u8], thumb: Option<&[u8]>, mime_type: &str, attributes: &[&[u8]], stickers: Option<&[&[u8]]>, video_cover: Option<&[u8]>, video_timestamp: Option<i32>, ttl_seconds: Option<i32>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x037c9330).unwrap();
    let flags_val: u32 = (if nosound_video { 1u32 << 3 } else { 0 }) | (if force_file { 1u32 << 4 } else { 0 }) | (if spoiler { 1u32 << 5 } else { 0 }) | (if thumb.is_some() { 1u32 << 2 } else { 0 }) | (if stickers.is_some() { 1u32 << 0 } else { 0 }) | (if video_cover.is_some() { 1u32 << 6 } else { 0 }) | (if video_timestamp.is_some() { 1u32 << 7 } else { 0 }) | (if ttl_seconds.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(file);
    if let Some(v) = thumb {
        buf.extend_from_slice(v);
    }
    buf.extend(serialize_string(mime_type));
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(attributes.len() as u32).unwrap();
    for item in attributes { buf.extend_from_slice(item); }
    if let Some(v) = stickers {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = video_cover {
        buf.extend_from_slice(v);
    }
    if let Some(v) = video_timestamp {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = ttl_seconds {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    buf
}

