pub fn serialize_inputMediaPoll(poll: &[u8], correct_answers: Option<&[i32]>, attached_media: Option<&[u8]>, solution: Option<&str>, solution_entities: Option<&[&[u8]]>, solution_media: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x883a4108).unwrap();
    let flags_val: u32 = (if correct_answers.is_some() { 1u32 << 0 } else { 0 }) | (if attached_media.is_some() { 1u32 << 3 } else { 0 }) | (if solution.is_some() { 1u32 << 1 } else { 0 }) | (if solution_entities.is_some() { 1u32 << 1 } else { 0 }) | (if solution_media.is_some() { 1u32 << 2 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(poll);
    if let Some(v) = correct_answers {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for &item in v { buf.write_i32::<LittleEndian>(item).unwrap(); }
    }
    if let Some(v) = attached_media {
        buf.extend_from_slice(v);
    }
    if let Some(v) = solution {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = solution_entities {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = solution_media {
        buf.extend_from_slice(v);
    }
    buf
}

