pub fn serialize_photo(has_stickers: bool, id: i64, access_hash: i64, file_reference: &[u8], date: i32, sizes: &[&[u8]], video_sizes: Option<&[&[u8]]>, dc_id: i32) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xfb197a65).unwrap();
    let flags_val: u32 = (if has_stickers { 1u32 << 0 } else { 0 }) | (if video_sizes.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i64::<LittleEndian>(id).unwrap();
    buf.write_i64::<LittleEndian>(access_hash).unwrap();
    buf.extend(tl_serialize_bytes(file_reference));
    buf.write_i32::<LittleEndian>(date).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(sizes.len() as u32).unwrap();
    for item in sizes { buf.extend_from_slice(item); }
    if let Some(v) = video_sizes {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf.write_i32::<LittleEndian>(dc_id).unwrap();
    buf
}

