pub fn serialize_contact(user_id: i64, mutual: bool) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x145ade0b).unwrap();
    buf.write_i64::<LittleEndian>(user_id).unwrap();
    buf.write_u32::<LittleEndian>(if mutual { 0x997275b5 } else { 0xbc799737 }).unwrap();
    buf
}

