pub fn serialize_contacts_contacts(contacts: &[&[u8]], saved_count: i32, users: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xeae87e42).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(contacts.len() as u32).unwrap();
    for item in contacts { buf.extend_from_slice(item); }
    buf.write_i32::<LittleEndian>(saved_count).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(users.len() as u32).unwrap();
    for item in users { buf.extend_from_slice(item); }
    buf
}

