    let flags_val: u32 = (if can_not_skip { 1u32 << 0 } else { 0 }) | (if document.is_some() { 1u32 << 1 } else { 0 }) | (if url.is_some() { 1u32 << 2 } else { 0 }) | (if sticker.is_some() { 1u32 << 3 } else { 0 });
