pub fn serialize_account_password(has_recovery: bool, has_secure_values: bool, has_password: bool, current_algo: Option<&[u8]>, srp_B: Option<&[u8]>, srp_id: Option<i64>, hint: Option<&str>, email_unconfirmed_pattern: Option<&str>, new_algo: &[u8], new_secure_algo: &[u8], secure_random: &[u8], pending_reset_date: Option<i32>, login_email_pattern: Option<&str>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x957b50fb).unwrap();
    let flags_val: u32 = (if has_recovery { 1u32 << 0 } else { 0 }) | (if has_secure_values { 1u32 << 1 } else { 0 }) | (if has_password { 1u32 << 2 } else { 0 }) | (if current_algo.is_some() { 1u32 << 2 } else { 0 }) | (if srp_B.is_some() { 1u32 << 2 } else { 0 }) | (if srp_id.is_some() { 1u32 << 2 } else { 0 }) | (if hint.is_some() { 1u32 << 3 } else { 0 }) | (if email_unconfirmed_pattern.is_some() { 1u32 << 4 } else { 0 }) | (if pending_reset_date.is_some() { 1u32 << 5 } else { 0 }) | (if login_email_pattern.is_some() { 1u32 << 6 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = current_algo {
        buf.extend_from_slice(v);
    }
    if let Some(v) = srp_B {
        buf.extend(tl_serialize_bytes(v));
    }
    if let Some(v) = srp_id {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = hint {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = email_unconfirmed_pattern {
        buf.extend(serialize_string(v));
    }
    buf.extend_from_slice(new_algo);
    buf.extend_from_slice(new_secure_algo);
    buf.extend(tl_serialize_bytes(secure_random));
    if let Some(v) = pending_reset_date {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = login_email_pattern {
        buf.extend(serialize_string(v));
    }
    buf
}

