pub fn serialize_channelParticipantsMentions(q: Option<&str>, top_msg_id: Option<i32>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xe04b5ceb).unwrap();
    let flags_val: u32 = (if q.is_some() { 1u32 << 0 } else { 0 }) | (if top_msg_id.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = q {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = top_msg_id {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    buf
}

pub fn serialize_channels_channelParticipants(count: i32, participants: &[&[u8]], chats: &[&[u8]], users: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x9ab0feaf).unwrap();
    buf.write_i32::<LittleEndian>(count).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(participants.len() as u32).unwrap();
    for item in participants { buf.extend_from_slice(item); }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(chats.len() as u32).unwrap();
    for item in chats { buf.extend_from_slice(item); }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(users.len() as u32).unwrap();
    for item in users { buf.extend_from_slice(item); }
    buf
}

pub fn serialize_channels_channelParticipant(participant: &[u8], chats: &[&[u8]], users: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xdfb80317).unwrap();
    buf.extend_from_slice(participant);
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(chats.len() as u32).unwrap();
    for item in chats { buf.extend_from_slice(item); }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(users.len() as u32).unwrap();
    for item in users { buf.extend_from_slice(item); }
    buf
}

