    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend_from_slice(id);
    buf.extend(serialize_string(text));
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(entities.len() as u32).unwrap();
    for item in entities { buf.extend_from_slice(item); }
