pub fn serialize_messageFwdHeader(imported: bool, saved_out: bool, from_id: Option<&[u8]>, from_name: Option<&str>, date: i32, channel_post: Option<i32>, post_author: Option<&str>, saved_from_peer: Option<&[u8]>, saved_from_msg_id: Option<i32>, saved_from_id: Option<&[u8]>, saved_from_name: Option<&str>, saved_date: Option<i32>, psa_type: Option<&str>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x4e4df4bb).unwrap();
    let flags_val: u32 = (if imported { 1u32 << 7 } else { 0 }) | (if saved_out { 1u32 << 11 } else { 0 }) | (if from_id.is_some() { 1u32 << 0 } else { 0 }) | (if from_name.is_some() { 1u32 << 5 } else { 0 }) | (if channel_post.is_some() { 1u32 << 2 } else { 0 }) | (if post_author.is_some() { 1u32 << 3 } else { 0 }) | (if saved_from_peer.is_some() { 1u32 << 4 } else { 0 }) | (if saved_from_msg_id.is_some() { 1u32 << 4 } else { 0 }) | (if saved_from_id.is_some() { 1u32 << 8 } else { 0 }) | (if saved_from_name.is_some() { 1u32 << 9 } else { 0 }) | (if saved_date.is_some() { 1u32 << 10 } else { 0 }) | (if psa_type.is_some() { 1u32 << 6 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = from_id {
        buf.extend_from_slice(v);
    }
    if let Some(v) = from_name {
        buf.extend(serialize_string(v));
    }
    buf.write_i32::<LittleEndian>(date).unwrap();
    if let Some(v) = channel_post {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = post_author {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = saved_from_peer {
        buf.extend_from_slice(v);
    }
    if let Some(v) = saved_from_msg_id {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = saved_from_id {
        buf.extend_from_slice(v);
    }
    if let Some(v) = saved_from_name {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = saved_date {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = psa_type {
        buf.extend(serialize_string(v));
    }
    buf
}

