pub fn serialize_invoice(test: bool, name_requested: bool, phone_requested: bool, email_requested: bool, shipping_address_requested: bool, flexible: bool, phone_to_provider: bool, email_to_provider: bool, recurring: bool, currency: &str, prices: &[&[u8]], max_tip_amount: Option<i64>, suggested_tip_amounts: Option<&[i64]>, terms_url: Option<&str>, subscription_period: Option<i32>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x049ee584).unwrap();
    let flags_val: u32 = (if test { 1u32 << 0 } else { 0 }) | (if name_requested { 1u32 << 1 } else { 0 }) | (if phone_requested { 1u32 << 2 } else { 0 }) | (if email_requested { 1u32 << 3 } else { 0 }) | (if shipping_address_requested { 1u32 << 4 } else { 0 }) | (if flexible { 1u32 << 5 } else { 0 }) | (if phone_to_provider { 1u32 << 6 } else { 0 }) | (if email_to_provider { 1u32 << 7 } else { 0 }) | (if recurring { 1u32 << 9 } else { 0 }) | (if max_tip_amount.is_some() { 1u32 << 8 } else { 0 }) | (if suggested_tip_amounts.is_some() { 1u32 << 8 } else { 0 }) | (if terms_url.is_some() { 1u32 << 10 } else { 0 }) | (if subscription_period.is_some() { 1u32 << 11 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend(serialize_string(currency));
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(prices.len() as u32).unwrap();
    for item in prices { buf.extend_from_slice(item); }
    if let Some(v) = max_tip_amount {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = suggested_tip_amounts {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for &item in v { buf.write_i64::<LittleEndian>(item).unwrap(); }
    }
    if let Some(v) = terms_url {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = subscription_period {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    buf
}

