pub fn serialize_payments_paymentForm(can_save_credentials: bool, password_missing: bool, form_id: i64, bot_id: i64, title: &str, description: &str, photo: Option<&[u8]>, invoice: &[u8], provider_id: i64, url: &str, native_provider: Option<&str>, native_params: Option<&[u8]>, additional_methods: Option<&[&[u8]]>, saved_info: Option<&[u8]>, saved_credentials: Option<&[&[u8]]>, users: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xa0058751).unwrap();
    let flags_val: u32 = (if can_save_credentials { 1u32 << 2 } else { 0 }) | (if password_missing { 1u32 << 3 } else { 0 }) | (if photo.is_some() { 1u32 << 5 } else { 0 }) | (if native_provider.is_some() { 1u32 << 4 } else { 0 }) | (if native_params.is_some() { 1u32 << 4 } else { 0 }) | (if additional_methods.is_some() { 1u32 << 6 } else { 0 }) | (if saved_info.is_some() { 1u32 << 0 } else { 0 }) | (if saved_credentials.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i64::<LittleEndian>(form_id).unwrap();
    buf.write_i64::<LittleEndian>(bot_id).unwrap();
    buf.extend(serialize_string(title));
    buf.extend(serialize_string(description));
    if let Some(v) = photo {
        buf.extend_from_slice(v);
    }
    buf.extend_from_slice(invoice);
    buf.write_i64::<LittleEndian>(provider_id).unwrap();
    buf.extend(serialize_string(url));
    if let Some(v) = native_provider {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = native_params {
        buf.extend_from_slice(v);
    }
    if let Some(v) = additional_methods {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = saved_info {
        buf.extend_from_slice(v);
    }
    if let Some(v) = saved_credentials {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(users.len() as u32).unwrap();
    for item in users { buf.extend_from_slice(item); }
    buf
}

