pub fn serialize_phoneCall(p2p_allowed: bool, video: bool, conference_supported: bool, id: i64, access_hash: i64, date: i32, admin_id: i64, participant_id: i64, g_a_or_b: &[u8], key_fingerprint: i64, protocol: &[u8], connections: &[&[u8]], start_date: i32, custom_parameters: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x30535af5).unwrap();
    let flags_val: u32 = (if p2p_allowed { 1u32 << 5 } else { 0 }) | (if video { 1u32 << 6 } else { 0 }) | (if conference_supported { 1u32 << 8 } else { 0 }) | (if custom_parameters.is_some() { 1u32 << 7 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i64::<LittleEndian>(id).unwrap();
    buf.write_i64::<LittleEndian>(access_hash).unwrap();
    buf.write_i32::<LittleEndian>(date).unwrap();
    buf.write_i64::<LittleEndian>(admin_id).unwrap();
    buf.write_i64::<LittleEndian>(participant_id).unwrap();
    buf.extend(tl_serialize_bytes(g_a_or_b));
    buf.write_i64::<LittleEndian>(key_fingerprint).unwrap();
    buf.extend_from_slice(protocol);
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(connections.len() as u32).unwrap();
    for item in connections { buf.extend_from_slice(item); }
    buf.write_i32::<LittleEndian>(start_date).unwrap();
    if let Some(v) = custom_parameters {
        buf.extend_from_slice(v);
    }
    buf
}

