pub fn serialize_langPackDifference(lang_code: &str, from_version: i32, version: i32, strings: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xf385c1f6).unwrap();
    buf.extend(serialize_string(lang_code));
    buf.write_i32::<LittleEndian>(from_version).unwrap();
    buf.write_i32::<LittleEndian>(version).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(strings.len() as u32).unwrap();
    for item in strings { buf.extend_from_slice(item); }
    buf
}

pub fn serialize_langPackLanguage(official: bool, rtl: bool, beta: bool, name: &str, native_name: &str, lang_code: &str, base_lang_code: Option<&str>, plural_code: &str, strings_count: i32, translated_count: i32, translations_url: &str) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xeeca5ce3).unwrap();
    let flags_val: u32 = (if official { 1u32 << 0 } else { 0 }) | (if rtl { 1u32 << 2 } else { 0 }) | (if beta { 1u32 << 3 } else { 0 }) | (if base_lang_code.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend(serialize_string(name));
    buf.extend(serialize_string(native_name));
    buf.extend(serialize_string(lang_code));
    if let Some(v) = base_lang_code {
        buf.extend(serialize_string(v));
    }
    buf.extend(serialize_string(plural_code));
    buf.write_i32::<LittleEndian>(strings_count).unwrap();
    buf.write_i32::<LittleEndian>(translated_count).unwrap();
    buf.extend(serialize_string(translations_url));
    buf
}

