pub fn serialize_poll(id: i64, closed: bool, public_voters: bool, multiple_choice: bool, quiz: bool, open_answers: bool, revoting_disabled: bool, shuffle_answers: bool, hide_results_until_close: bool, creator: bool, subscribers_only: bool, question: &[u8], answers: &[&[u8]], close_period: Option<i32>, close_date: Option<i32>, countries_iso2: Option<&[&str]>, hash: i64) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x966e2dbf).unwrap();
    let flags_val: u32 = (if closed { 1u32 << 0 } else { 0 }) | (if public_voters { 1u32 << 1 } else { 0 }) | (if multiple_choice { 1u32 << 2 } else { 0 }) | (if quiz { 1u32 << 3 } else { 0 }) | (if open_answers { 1u32 << 6 } else { 0 }) | (if revoting_disabled { 1u32 << 7 } else { 0 }) | (if shuffle_answers { 1u32 << 8 } else { 0 }) | (if hide_results_until_close { 1u32 << 9 } else { 0 }) | (if creator { 1u32 << 10 } else { 0 }) | (if subscribers_only { 1u32 << 11 } else { 0 }) | (if close_period.is_some() { 1u32 << 4 } else { 0 }) | (if close_date.is_some() { 1u32 << 5 } else { 0 }) | (if countries_iso2.is_some() { 1u32 << 12 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i64::<LittleEndian>(id).unwrap();
    buf.extend_from_slice(question);
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(answers.len() as u32).unwrap();
    for item in answers { buf.extend_from_slice(item); }
    if let Some(v) = close_period {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = close_date {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = countries_iso2 {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend(serialize_string(item)); }
    }
    buf.write_i64::<LittleEndian>(hash).unwrap();
    buf
}

