pub fn serialize_sponsoredMessage(recommended: bool, can_report: bool, random_id: &[u8], url: &str, title: &str, message: &str, entities: Option<&[&[u8]]>, photo: Option<&[u8]>, media: Option<&[u8]>, color: Option<&[u8]>, button_text: &str, sponsor_info: Option<&str>, additional_info: Option<&str>, min_display_duration: Option<i32>, max_display_duration: Option<i32>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x7dbf8673).unwrap();
    let flags_val: u32 = (if recommended { 1u32 << 5 } else { 0 }) | (if can_report { 1u32 << 12 } else { 0 }) | (if entities.is_some() { 1u32 << 1 } else { 0 }) | (if photo.is_some() { 1u32 << 6 } else { 0 }) | (if media.is_some() { 1u32 << 14 } else { 0 }) | (if color.is_some() { 1u32 << 13 } else { 0 }) | (if sponsor_info.is_some() { 1u32 << 7 } else { 0 }) | (if additional_info.is_some() { 1u32 << 8 } else { 0 }) | (if min_display_duration.is_some() { 1u32 << 15 } else { 0 }) | (if max_display_duration.is_some() { 1u32 << 15 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.extend(tl_serialize_bytes(random_id));
    buf.extend(serialize_string(url));
    buf.extend(serialize_string(title));
    buf.extend(serialize_string(message));
    if let Some(v) = entities {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = photo {
        buf.extend_from_slice(v);
    }
    if let Some(v) = media {
        buf.extend_from_slice(v);
    }
    if let Some(v) = color {
        buf.extend_from_slice(v);
    }
    buf.extend(serialize_string(button_text));
    if let Some(v) = sponsor_info {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = additional_info {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = min_display_duration {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = max_display_duration {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    buf
}

pub fn serialize_messages_sponsoredMessages(posts_between: Option<i32>, start_delay: Option<i32>, between_delay: Option<i32>, messages: &[&[u8]], chats: &[&[u8]], users: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xffda656d).unwrap();
    let flags_val: u32 = (if posts_between.is_some() { 1u32 << 0 } else { 0 }) | (if start_delay.is_some() { 1u32 << 1 } else { 0 }) | (if between_delay.is_some() { 1u32 << 2 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = posts_between {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = start_delay {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = between_delay {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(messages.len() as u32).unwrap();
    for item in messages { buf.extend_from_slice(item); }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(chats.len() as u32).unwrap();
    for item in chats { buf.extend_from_slice(item); }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(users.len() as u32).unwrap();
    for item in users { buf.extend_from_slice(item); }
    buf
}

