pub fn serialize_storyItem(pinned: bool, public: bool, close_friends: bool, min: bool, noforwards: bool, edited: bool, contacts: bool, selected_contacts: bool, out: bool, id: i32, date: i32, from_id: Option<&[u8]>, fwd_from: Option<&[u8]>, expire_date: i32, caption: Option<&str>, entities: Option<&[&[u8]]>, media: &[u8], media_areas: Option<&[&[u8]]>, privacy: Option<&[&[u8]]>, views: Option<&[u8]>, sent_reaction: Option<&[u8]>, albums: Option<&[i32]>, music: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x16a4b93c).unwrap();
    let flags_val: u32 = (if pinned { 1u32 << 5 } else { 0 }) | (if public { 1u32 << 7 } else { 0 }) | (if close_friends { 1u32 << 8 } else { 0 }) | (if min { 1u32 << 9 } else { 0 }) | (if noforwards { 1u32 << 10 } else { 0 }) | (if edited { 1u32 << 11 } else { 0 }) | (if contacts { 1u32 << 12 } else { 0 }) | (if selected_contacts { 1u32 << 13 } else { 0 }) | (if out { 1u32 << 16 } else { 0 }) | (if from_id.is_some() { 1u32 << 18 } else { 0 }) | (if fwd_from.is_some() { 1u32 << 17 } else { 0 }) | (if caption.is_some() { 1u32 << 0 } else { 0 }) | (if entities.is_some() { 1u32 << 1 } else { 0 }) | (if media_areas.is_some() { 1u32 << 14 } else { 0 }) | (if privacy.is_some() { 1u32 << 2 } else { 0 }) | (if views.is_some() { 1u32 << 3 } else { 0 }) | (if sent_reaction.is_some() { 1u32 << 15 } else { 0 }) | (if albums.is_some() { 1u32 << 19 } else { 0 }) | (if music.is_some() { 1u32 << 20 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i32::<LittleEndian>(id).unwrap();
    buf.write_i32::<LittleEndian>(date).unwrap();
    if let Some(v) = from_id {
        buf.extend_from_slice(v);
    }
    if let Some(v) = fwd_from {
        buf.extend_from_slice(v);
    }
    buf.write_i32::<LittleEndian>(expire_date).unwrap();
    if let Some(v) = caption {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = entities {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf.extend_from_slice(media);
    if let Some(v) = media_areas {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = privacy {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = views {
        buf.extend_from_slice(v);
    }
    if let Some(v) = sent_reaction {
        buf.extend_from_slice(v);
    }
    if let Some(v) = albums {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for &item in v { buf.write_i32::<LittleEndian>(item).unwrap(); }
    }
    if let Some(v) = music {
        buf.extend_from_slice(v);
    }
    buf
}

