    let flags_val: u32 = (if my_boost { 1u32 << 2 } else { 0 }) | (if gift_boosts.is_some() { 1u32 << 4 } else { 0 }) | (if next_level_boosts.is_some() { 1u32 << 0 } else { 0 }) | (if premium_audience.is_some() { 1u32 << 1 } else { 0 }) | (if prepaid_giveaways.is_some() { 1u32 << 3 } else { 0 }) | (if my_boost_slots.is_some() { 1u32 << 2 } else { 0 });
