    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xb9c0639a).unwrap();
    let flags_val: u32 = (if dark_accent_color.is_some() { 1u32 << 0 } else { 0 }) | (if dark_colors.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
