pub fn serialize_inputBusinessBotRecipients(existing_chats: bool, new_chats: bool, contacts: bool, non_contacts: bool, exclude_selected: bool, users: Option<&[&[u8]]>, exclude_users: Option<&[&[u8]]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xc4e5921e).unwrap();
    let flags_val: u32 = (if existing_chats { 1u32 << 0 } else { 0 }) | (if new_chats { 1u32 << 1 } else { 0 }) | (if contacts { 1u32 << 2 } else { 0 }) | (if non_contacts { 1u32 << 3 } else { 0 }) | (if exclude_selected { 1u32 << 5 } else { 0 }) | (if users.is_some() { 1u32 << 4 } else { 0 }) | (if exclude_users.is_some() { 1u32 << 6 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = users {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    if let Some(v) = exclude_users {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf
}

