pub fn serialize_aiComposeTone(creator: bool, id: i64, access_hash: i64, slug: &str, title: &str, emoji_id: Option<i64>, prompt: Option<&str>, installs_count: Option<i32>, author_id: Option<i64>, example_english: Option<&[u8]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xcff63ea9).unwrap();
    let flags_val: u32 = (if creator { 1u32 << 0 } else { 0 }) | (if emoji_id.is_some() { 1u32 << 1 } else { 0 }) | (if prompt.is_some() { 1u32 << 4 } else { 0 }) | (if installs_count.is_some() { 1u32 << 2 } else { 0 }) | (if author_id.is_some() { 1u32 << 3 } else { 0 }) | (if example_english.is_some() { 1u32 << 5 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    buf.write_i64::<LittleEndian>(id).unwrap();
    buf.write_i64::<LittleEndian>(access_hash).unwrap();
    buf.extend(serialize_string(slug));
    buf.extend(serialize_string(title));
    if let Some(v) = emoji_id {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = prompt {
        buf.extend(serialize_string(v));
    }
    if let Some(v) = installs_count {
        buf.write_i32::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = author_id {
        buf.write_i64::<LittleEndian>(v).unwrap();
    }
    if let Some(v) = example_english {
        buf.extend_from_slice(v);
    }
    buf
}

pub fn serialize_aiComposeToneDefault(tone: &str, emoji_id: i64, title: &str) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x9bad6414).unwrap();
    buf.extend(serialize_string(tone));
    buf.write_i64::<LittleEndian>(emoji_id).unwrap();
    buf.extend(serialize_string(title));
    buf
}

pub fn serialize_aicompose_tones(hash: i64, tones: &[&[u8]], users: &[&[u8]]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0x6c9d0efe).unwrap();
    buf.write_i64::<LittleEndian>(hash).unwrap();
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(tones.len() as u32).unwrap();
    for item in tones { buf.extend_from_slice(item); }
    buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
    buf.write_u32::<LittleEndian>(users.len() as u32).unwrap();
    for item in users { buf.extend_from_slice(item); }
    buf
}

pub fn serialize_aiComposeToneExample(from: &[u8], to: &[u8]) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xf1d628ec).unwrap();
    buf.extend_from_slice(from);
    buf.extend_from_slice(to);
    buf
}

pub fn serialize_bots_accessSettings(restricted: bool, add_users: Option<&[&[u8]]>) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.write_u32::<LittleEndian>(0xdd1fbf93).unwrap();
    let flags_val: u32 = (if restricted { 1u32 << 0 } else { 0 }) | (if add_users.is_some() { 1u32 << 1 } else { 0 });
    buf.write_u32::<LittleEndian>(flags_val).unwrap();
    if let Some(v) = add_users {
        buf.write_u32::<LittleEndian>(0x1cb5c415).unwrap();
        buf.write_u32::<LittleEndian>(v.len() as u32).unwrap();
        for item in v { buf.extend_from_slice(item); }
    }
    buf
}

