#[derive(Debug, Clone)]
pub enum TlBotInlineResult {
    Result { id: String, r#type: String, title: Option<String>, description: Option<String>, url: Option<String>, thumb: Option<Vec<u8>>, content: Option<Vec<u8>>, send_message: Vec<u8> },
    MediaResult { id: String, r#type: String, photo: Option<Vec<u8>>, document: Option<Vec<u8>>, title: Option<String>, description: Option<String>, send_message: Vec<u8> },
}

impl TlBotInlineResult {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0x11965f3a => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let id = {
                    deserialize_string(cursor)?
                };
                let r#type = {
                    deserialize_string(cursor)?
                };
                let title = if flags & (1 << 1) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let description = if flags & (1 << 2) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let url = if flags & (1 << 3) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let thumb = if flags & (1 << 4) != 0 {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; Some(cursor.get_ref()[s..e].to_vec()) }
                } else { None };
                let content = if flags & (1 << 5) != 0 {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; Some(cursor.get_ref()[s..e].to_vec()) }
                } else { None };
                let send_message = {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; cursor.get_ref()[s..e].to_vec() }
                };
                Ok(TlBotInlineResult::Result { id, r#type, title, description, url, thumb, content, send_message })
            }
            0x17db940b => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let id = {
                    deserialize_string(cursor)?
                };
                let r#type = {
                    deserialize_string(cursor)?
                };
                let photo = if flags & (1 << 0) != 0 {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; Some(cursor.get_ref()[s..e].to_vec()) }
                } else { None };
                let document = if flags & (1 << 1) != 0 {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; Some(cursor.get_ref()[s..e].to_vec()) }
                } else { None };
                let title = if flags & (1 << 2) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let description = if flags & (1 << 3) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let send_message = {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; cursor.get_ref()[s..e].to_vec() }
                };
                Ok(TlBotInlineResult::MediaResult { id, r#type, photo, document, title, description, send_message })
            }
            _ => Err(format!("unknown BotInlineResult ctor {:#x}", ctor)),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct TlPaymentsSuggestedStarRefBots {
    pub count: i32,
    pub suggested_bots: Vec<Vec<u8>>,
    pub users: Vec<Vec<u8>>,
    pub next_offset: Option<String>,
}

impl TlPaymentsSuggestedStarRefBots {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.count = cursor.read_i32::<LittleEndian>().map_err(|_| "read count")?;
        {
            let _vc = cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
            let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec cnt")?;
            let mut v = Vec::with_capacity(cnt as usize);
            for _ in 0..cnt {
                let s = cursor.position() as usize;
                skip_tl(cursor)?;
                let e = cursor.position() as usize;
                v.push(cursor.get_ref()[s..e].to_vec());
            }
            obj.suggested_bots = v;
        }
        {
            let _vc = cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
            let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec cnt")?;
            let mut v = Vec::with_capacity(cnt as usize);
            for _ in 0..cnt {
                let s = cursor.position() as usize;
                skip_tl(cursor)?;
                let e = cursor.position() as usize;
                v.push(cursor.get_ref()[s..e].to_vec());
            }
            obj.users = v;
        }
        if flags & (1 << 0) != 0 {
            obj.next_offset = Some(deserialize_string(cursor)?);
        }
        Ok(obj)
    }
}

