#[derive(Debug, Clone)]
pub enum TlAuthAuthorization {
    Authorization { setup_password_required: bool, otherwise_relogin_days: Option<i32>, tmp_sessions: Option<i32>, future_auth_token: Option<Vec<u8>>, user: Vec<u8> },
    SignUpRequired { terms_of_service: Option<Vec<u8>> },
}

impl TlAuthAuthorization {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0x2ea2c0d4 => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let setup_password_required = flags & (1 << 1) != 0;
                let otherwise_relogin_days = if flags & (1 << 1) != 0 {
                    Some(cursor.read_i32::<LittleEndian>().map_err(|_| "int")?)
                } else { None };
                let tmp_sessions = if flags & (1 << 0) != 0 {
                    Some(cursor.read_i32::<LittleEndian>().map_err(|_| "int")?)
                } else { None };
                let future_auth_token = if flags & (1 << 2) != 0 {
                    Some(deserialize_bytes(cursor).map_err(|_| "bytes".to_string())?)
                } else { None };
                let user = {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; cursor.get_ref()[s..e].to_vec() }
                };
                Ok(TlAuthAuthorization::Authorization { setup_password_required, otherwise_relogin_days, tmp_sessions, future_auth_token, user })
            }
            0x44747e9a => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let terms_of_service = if flags & (1 << 0) != 0 {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; Some(cursor.get_ref()[s..e].to_vec()) }
                } else { None };
                Ok(TlAuthAuthorization::SignUpRequired { terms_of_service })
            }
            _ => Err(format!("unknown auth.Authorization ctor {:#x}", ctor)),
        }
    }
}

#[derive(Debug, Clone)]
pub enum TlInputUser {
    Empty,
    Myself,
    InputUser { user_id: i64, access_hash: i64 },
    FromMessage { peer: Vec<u8>, msg_id: i32, user_id: i64 },
}

impl TlInputUser {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0xb98886cf => {
                Ok(TlInputUser::Empty)
            }
            0xf7c1b13f => {
                Ok(TlInputUser::Myself)
            }
            0xf21158c6 => {
                let user_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                let access_hash = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputUser::InputUser { user_id, access_hash })
            }
            0x1da448e2 => {
                let peer = {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; cursor.get_ref()[s..e].to_vec() }
                };
                let msg_id = {
                    cursor.read_i32::<LittleEndian>().map_err(|_| "int")?
                };
                let user_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputUser::FromMessage { peer, msg_id, user_id })
            }
            _ => Err(format!("unknown InputUser ctor {:#x}", ctor)),
        }
    }
}

