#[derive(Debug, Clone, Default)]
pub struct TlAccountPassword {
    pub has_recovery: bool,
    pub has_secure_values: bool,
    pub has_password: bool,
    pub current_algo: Option<Vec<u8>>,
    pub srp_B: Option<Vec<u8>>,
    pub srp_id: Option<i64>,
    pub hint: Option<String>,
    pub email_unconfirmed_pattern: Option<String>,
    pub new_algo: Vec<u8>,
    pub new_secure_algo: Vec<u8>,
    pub secure_random: Vec<u8>,
    pub pending_reset_date: Option<i32>,
    pub login_email_pattern: Option<String>,
}

impl TlAccountPassword {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.has_recovery = flags & (1 << 0) != 0;
        obj.has_secure_values = flags & (1 << 1) != 0;
        obj.has_password = flags & (1 << 2) != 0;
        if flags & (1 << 2) != 0 {
            {
                let start = cursor.position() as usize;
                skip_tl(cursor)?;
                let end = cursor.position() as usize;
                let slice = cursor.get_ref();
                obj.current_algo = Some(slice[start..end].to_vec());
            }
        }
        if flags & (1 << 2) != 0 {
            obj.srp_B = Some(deserialize_bytes(cursor).map_err(|_| "read srp_B".to_string())?);
        }
        if flags & (1 << 2) != 0 {
            obj.srp_id = Some(cursor.read_i64::<LittleEndian>().map_err(|_| "read srp_id")?);
        }
        if flags & (1 << 3) != 0 {
            obj.hint = Some(deserialize_string(cursor)?);
        }
        if flags & (1 << 4) != 0 {
            obj.email_unconfirmed_pattern = Some(deserialize_string(cursor)?);
        }
        {
            let start = cursor.position() as usize;
            skip_tl(cursor)?;
            let end = cursor.position() as usize;
            let slice = cursor.get_ref();
            obj.new_algo = slice[start..end].to_vec();
        }
        {
            let start = cursor.position() as usize;
            skip_tl(cursor)?;
            let end = cursor.position() as usize;
            let slice = cursor.get_ref();
            obj.new_secure_algo = slice[start..end].to_vec();
        }
        obj.secure_random = deserialize_bytes(cursor).map_err(|_| "read secure_random".to_string())?;
        if flags & (1 << 5) != 0 {
            obj.pending_reset_date = Some(cursor.read_i32::<LittleEndian>().map_err(|_| "read pending_reset_date")?);
        }
        if flags & (1 << 6) != 0 {
            obj.login_email_pattern = Some(deserialize_string(cursor)?);
        }
        Ok(obj)
    }
}

