pub struct TlPoll {
    pub id: i64,
    pub closed: bool,
    pub public_voters: bool,
    pub multiple_choice: bool,
    pub quiz: bool,
    pub open_answers: bool,
    pub revoting_disabled: bool,
    pub shuffle_answers: bool,
    pub hide_results_until_close: bool,
    pub creator: bool,
    pub subscribers_only: bool,
    pub question: Vec<u8>,
    pub answers: Vec<Vec<u8>>,
    pub close_period: Option<i32>,
    pub close_date: Option<i32>,
    pub countries_iso2: Option<Vec<String>>,
    pub hash: i64,
}

impl TlPoll {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.id = cursor.read_i64::<LittleEndian>().map_err(|_| "read id")?;
        obj.closed = flags & (1 << 0) != 0;
        obj.public_voters = flags & (1 << 1) != 0;
        obj.multiple_choice = flags & (1 << 2) != 0;
        obj.quiz = flags & (1 << 3) != 0;
        obj.open_answers = flags & (1 << 6) != 0;
        obj.revoting_disabled = flags & (1 << 7) != 0;
        obj.shuffle_answers = flags & (1 << 8) != 0;
        obj.hide_results_until_close = flags & (1 << 9) != 0;
        obj.creator = flags & (1 << 10) != 0;
        obj.subscribers_only = flags & (1 << 11) != 0;
        {
            let start = cursor.position() as usize;
            skip_tl(cursor)?;
            let end = cursor.position() as usize;
            let slice = cursor.get_ref();
            obj.question = slice[start..end].to_vec();
        }
        {
            let _vc = cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
            let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec cnt")?;
            let mut v = Vec::with_capacity(cnt as usize);
            for _ in 0..cnt {
                let s = cursor.position() as usize;
                skip_tl(cursor)?;
                let e = cursor.position() as usize;
                v.push(cursor.get_ref()[s..e].to_vec());
            }
            obj.answers = v;
        }
        if flags & (1 << 4) != 0 {
            obj.close_period = Some(cursor.read_i32::<LittleEndian>().map_err(|_| "read close_period")?);
        }
        if flags & (1 << 5) != 0 {
            obj.close_date = Some(cursor.read_i32::<LittleEndian>().map_err(|_| "read close_date")?);
        }
        if flags & (1 << 12) != 0 {
            obj.countries_iso2 = Some(read_vector_string(cursor)?);
        }
        obj.hash = cursor.read_i64::<LittleEndian>().map_err(|_| "read hash")?;
        Ok(obj)
    }
}

