#[derive(Debug, Clone)]
pub enum TlMessagesStickers {
    NotModified,
    Stickers { hash: i64, stickers: Vec<Vec<u8>> },
}

impl TlMessagesStickers {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0xf1749a22 => {
                Ok(TlMessagesStickers::NotModified)
            }
            0x30a6ec7e => {
                let hash = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                let stickers = {
                    { let _vc = cursor.read_u32::<LittleEndian>().map_err(|_| "vc")?; let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "cnt")?; let mut v = Vec::new(); for _ in 0..cnt { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; v.push(cursor.get_ref()[s..e].to_vec()); } v }
                };
                Ok(TlMessagesStickers::Stickers { hash, stickers })
            }
            _ => Err(format!("unknown messages.Stickers ctor {:#x}", ctor)),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct TlSuggestedPost {
    pub accepted: bool,
    pub rejected: bool,
    pub price: Option<Vec<u8>>,
    pub schedule_date: Option<i32>,
}

impl TlSuggestedPost {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.accepted = flags & (1 << 1) != 0;
        obj.rejected = flags & (1 << 2) != 0;
        if flags & (1 << 3) != 0 {
            {
                let start = cursor.position() as usize;
                skip_tl(cursor)?;
                let end = cursor.position() as usize;
                let slice = cursor.get_ref();
                obj.price = Some(slice[start..end].to_vec());
            }
        }
        if flags & (1 << 0) != 0 {
            obj.schedule_date = Some(cursor.read_i32::<LittleEndian>().map_err(|_| "read schedule_date")?);
        }
        Ok(obj)
    }
}

#[derive(Debug, Clone, Default)]
pub struct TlSponsoredPeer {
    pub random_id: Vec<u8>,
    pub peer: Vec<u8>,
    pub sponsor_info: Option<String>,
    pub additional_info: Option<String>,
}

impl TlSponsoredPeer {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.random_id = deserialize_bytes(cursor).map_err(|_| "read random_id".to_string())?;
        {
            let start = cursor.position() as usize;
            skip_tl(cursor)?;
            let end = cursor.position() as usize;
            let slice = cursor.get_ref();
            obj.peer = slice[start..end].to_vec();
        }
        if flags & (1 << 0) != 0 {
            obj.sponsor_info = Some(deserialize_string(cursor)?);
        }
        if flags & (1 << 1) != 0 {
            obj.additional_info = Some(deserialize_string(cursor)?);
        }
        Ok(obj)
    }
}

