#[derive(Debug, Clone)]
pub enum TlInputPeer {
    Empty,
    Myself,
    Chat { chat_id: i64 },
    User { user_id: i64, access_hash: i64 },
    Channel { channel_id: i64, access_hash: i64 },
    UserFromMessage { peer: Vec<u8>, msg_id: i32, user_id: i64 },
    ChannelFromMessage { peer: Vec<u8>, msg_id: i32, channel_id: i64 },
}

impl TlInputPeer {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0x7f3b18ea => {
                Ok(TlInputPeer::Empty)
            }
            0x7da07ec9 => {
                Ok(TlInputPeer::Myself)
            }
            0x35a95cb9 => {
                let chat_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputPeer::Chat { chat_id })
            }
            0xdde8a54c => {
                let user_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                let access_hash = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputPeer::User { user_id, access_hash })
            }
            0x27bcbbfc => {
                let channel_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                let access_hash = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputPeer::Channel { channel_id, access_hash })
            }
            0xa87b0a1c => {
                let peer = {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; cursor.get_ref()[s..e].to_vec() }
                };
                let msg_id = {
                    cursor.read_i32::<LittleEndian>().map_err(|_| "int")?
                };
                let user_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputPeer::UserFromMessage { peer, msg_id, user_id })
            }
            0xbd2a0840 => {
                let peer = {
                    { let s = cursor.position() as usize; skip_tl(cursor)?; let e = cursor.position() as usize; cursor.get_ref()[s..e].to_vec() }
                };
                let msg_id = {
                    cursor.read_i32::<LittleEndian>().map_err(|_| "int")?
                };
                let channel_id = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                Ok(TlInputPeer::ChannelFromMessage { peer, msg_id, channel_id })
            }
            _ => Err(format!("unknown InputPeer ctor {:#x}", ctor)),
        }
    }
}

