#[derive(Debug, Clone)]
pub enum TlLangPackString {
    LangPackString { key: String, value: String },
    Pluralized { key: String, zero_value: Option<String>, one_value: Option<String>, two_value: Option<String>, few_value: Option<String>, many_value: Option<String>, other_value: String },
    Deleted { key: String },
}

impl TlLangPackString {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0xcad181f6 => {
                let key = {
                    deserialize_string(cursor)?
                };
                let value = {
                    deserialize_string(cursor)?
                };
                Ok(TlLangPackString::LangPackString { key, value })
            }
            0x6c47ac9f => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let key = {
                    deserialize_string(cursor)?
                };
                let zero_value = if flags & (1 << 0) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let one_value = if flags & (1 << 1) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let two_value = if flags & (1 << 2) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let few_value = if flags & (1 << 3) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let many_value = if flags & (1 << 4) != 0 {
                    Some(deserialize_string(cursor)?)
                } else { None };
                let other_value = {
                    deserialize_string(cursor)?
                };
                Ok(TlLangPackString::Pluralized { key, zero_value, one_value, two_value, few_value, many_value, other_value })
            }
            0x2979eeb2 => {
                let key = {
                    deserialize_string(cursor)?
                };
                Ok(TlLangPackString::Deleted { key })
            }
            _ => Err(format!("unknown LangPackString ctor {:#x}", ctor)),
        }
    }
}

