#[derive(Debug, Clone, Default)]
pub struct TlStarsSubscriptionPricing {
    pub period: i32,
    pub amount: i64,
}

impl TlStarsSubscriptionPricing {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        obj.period = cursor.read_i32::<LittleEndian>().map_err(|_| "read period")?;
        obj.amount = cursor.read_i64::<LittleEndian>().map_err(|_| "read amount")?;
        Ok(obj)
    }
}

#[derive(Debug, Clone)]
pub enum TlMessagesEmojiGameInfo {
    EmojiGameUnavailable,
    EmojiGameDiceInfo { game_hash: String, prev_stake: i64, current_streak: i32, params: Vec<i32>, plays_left: Option<i32> },
}

impl TlMessagesEmojiGameInfo {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0x59e65335 => {
                Ok(TlMessagesEmojiGameInfo::EmojiGameUnavailable)
            }
            0x44e56023 => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let game_hash = {
                    deserialize_string(cursor)?
                };
                let prev_stake = {
                    cursor.read_i64::<LittleEndian>().map_err(|_| "long")?
                };
                let current_streak = {
                    cursor.read_i32::<LittleEndian>().map_err(|_| "int")?
                };
                let params = {
                    read_vector_int(cursor)?
                };
                let plays_left = if flags & (1 << 0) != 0 {
                    Some(cursor.read_i32::<LittleEndian>().map_err(|_| "int")?)
                } else { None };
                Ok(TlMessagesEmojiGameInfo::EmojiGameDiceInfo { game_hash, prev_stake, current_streak, params, plays_left })
            }
            _ => Err(format!("unknown messages.EmojiGameInfo ctor {:#x}", ctor)),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct TlReceivedNotifyMessage {
    pub id: i32,
    pub flags: i32,
}

impl TlReceivedNotifyMessage {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        obj.id = cursor.read_i32::<LittleEndian>().map_err(|_| "read id")?;
        obj.flags = cursor.read_i32::<LittleEndian>().map_err(|_| "read flags")?;
        Ok(obj)
    }
}

#[derive(Debug, Clone, Default)]
pub struct TlStarsGiftOption {
    pub extended: bool,
    pub stars: i64,
    pub store_product: Option<String>,
    pub currency: String,
    pub amount: i64,
}

impl TlStarsGiftOption {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.extended = flags & (1 << 1) != 0;
        obj.stars = cursor.read_i64::<LittleEndian>().map_err(|_| "read stars")?;
        if flags & (1 << 0) != 0 {
            obj.store_product = Some(deserialize_string(cursor)?);
        }
        obj.currency = deserialize_string(cursor)?;
        obj.amount = cursor.read_i64::<LittleEndian>().map_err(|_| "read amount")?;
        Ok(obj)
    }
}

#[derive(Debug, Clone, Default)]
pub struct TlQuickReply {
    pub shortcut_id: i32,
    pub shortcut: String,
    pub top_message: i32,
    pub count: i32,
}

impl TlQuickReply {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        obj.shortcut_id = cursor.read_i32::<LittleEndian>().map_err(|_| "read shortcut_id")?;
        obj.shortcut = deserialize_string(cursor)?;
        obj.top_message = cursor.read_i32::<LittleEndian>().map_err(|_| "read top_message")?;
        obj.count = cursor.read_i32::<LittleEndian>().map_err(|_| "read count")?;
        Ok(obj)
    }
}

