        obj.preload_featured_stickers = flags & (1 << 4) != 0;
        obj.revoke_pm_inbox = flags & (1 << 6) != 0;
        obj.blocked_mode = flags & (1 << 8) != 0;
        obj.force_try_ipv6 = flags & (1 << 14) != 0;
