        obj.expires = cursor.read_i32::<LittleEndian>().map_err(|_| "read expires")?;
        obj.test_mode = cursor.read_u32::<LittleEndian>().map_err(|_| "read test_mode")? == 0x997275b5;
        obj.this_dc = cursor.read_i32::<LittleEndian>().map_err(|_| "read this_dc")?;
        {
            let _vc = cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
            let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec cnt")?;
            let mut v = Vec::with_capacity(cnt as usize);
            for _ in 0..cnt {
                let s = cursor.position() as usize;
                skip_tl(cursor)?;
                let e = cursor.position() as usize;
                v.push(cursor.get_ref()[s..e].to_vec());
            }
            obj.dc_options = v;
        }
        obj.dc_txt_domain_name = deserialize_string(cursor)?;
        obj.chat_size_max = cursor.read_i32::<LittleEndian>().map_err(|_| "read chat_size_max")?;
        obj.megagroup_size_max = cursor.read_i32::<LittleEndian>().map_err(|_| "read megagroup_size_max")?;
        obj.forwarded_count_max = cursor.read_i32::<LittleEndian>().map_err(|_| "read forwarded_count_max")?;
        obj.online_update_period_ms = cursor.read_i32::<LittleEndian>().map_err(|_| "read online_update_period_ms")?;
        obj.offline_blur_timeout_ms = cursor.read_i32::<LittleEndian>().map_err(|_| "read offline_blur_timeout_ms")?;
        obj.offline_idle_timeout_ms = cursor.read_i32::<LittleEndian>().map_err(|_| "read offline_idle_timeout_ms")?;
        obj.online_cloud_timeout_ms = cursor.read_i32::<LittleEndian>().map_err(|_| "read online_cloud_timeout_ms")?;
        obj.notify_cloud_delay_ms = cursor.read_i32::<LittleEndian>().map_err(|_| "read notify_cloud_delay_ms")?;
        obj.notify_default_delay_ms = cursor.read_i32::<LittleEndian>().map_err(|_| "read notify_default_delay_ms")?;
