#[derive(Debug, Clone)]
pub enum TlUserStatus {
    Empty,
    Online { expires: i32 },
    Offline { was_online: i32 },
    Recently { by_me: bool },
    LastWeek { by_me: bool },
    LastMonth { by_me: bool },
}

impl TlUserStatus {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let ctor = cursor.read_u32::<LittleEndian>().map_err(|_| "read ctor")?;
        Self::deserialize_by_id(cursor, ctor)
    }

    pub fn deserialize_by_id(cursor: &mut Cursor<&[u8]>, ctor: u32) -> Result<Self, String> {
        match ctor {
            0x09d05049 => {
                Ok(TlUserStatus::Empty)
            }
            0xedb93949 => {
                let expires = {
                    cursor.read_i32::<LittleEndian>().map_err(|_| "int")?
                };
                Ok(TlUserStatus::Online { expires })
            }
            0x008c703f => {
                let was_online = {
                    cursor.read_i32::<LittleEndian>().map_err(|_| "int")?
                };
                Ok(TlUserStatus::Offline { was_online })
            }
            0x7b197dc8 => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let by_me = flags & (1 << 0) != 0;
                Ok(TlUserStatus::Recently { by_me })
            }
            0x541a1d1a => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let by_me = flags & (1 << 0) != 0;
                Ok(TlUserStatus::LastWeek { by_me })
            }
            0x65899777 => {
                let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "flags")?;
                let by_me = flags & (1 << 0) != 0;
                Ok(TlUserStatus::LastMonth { by_me })
            }
            _ => Err(format!("unknown UserStatus ctor {:#x}", ctor)),
        }
    }
}

