#[derive(Debug, Clone, Default)]
pub struct TlMessageReplies {
    pub comments: bool,
    pub replies: i32,
    pub replies_pts: i32,
    pub recent_repliers: Option<Vec<Vec<u8>>>,
    pub channel_id: Option<i64>,
    pub max_id: Option<i32>,
    pub read_max_id: Option<i32>,
}

impl TlMessageReplies {
    pub fn deserialize(cursor: &mut Cursor<&[u8]>) -> Result<Self, String> {
        let mut obj = Self::default();
        let flags = cursor.read_u32::<LittleEndian>().map_err(|_| "read flags")?;
        obj.comments = flags & (1 << 0) != 0;
        obj.replies = cursor.read_i32::<LittleEndian>().map_err(|_| "read replies")?;
        obj.replies_pts = cursor.read_i32::<LittleEndian>().map_err(|_| "read replies_pts")?;
        if flags & (1 << 1) != 0 {
            {
                let _vc = cursor.read_u32::<LittleEndian>().map_err(|_| "vec ctor")?;
                let cnt = cursor.read_u32::<LittleEndian>().map_err(|_| "vec cnt")?;
                let mut v = Vec::with_capacity(cnt as usize);
                for _ in 0..cnt {
                    let s = cursor.position() as usize;
                    skip_tl(cursor)?;
                    let e = cursor.position() as usize;
                    v.push(cursor.get_ref()[s..e].to_vec());
                }
                obj.recent_repliers = Some(v);
            }
        }
        if flags & (1 << 0) != 0 {
            obj.channel_id = Some(cursor.read_i64::<LittleEndian>().map_err(|_| "read channel_id")?);
        }
        if flags & (1 << 2) != 0 {
            obj.max_id = Some(cursor.read_i32::<LittleEndian>().map_err(|_| "read max_id")?);
        }
        if flags & (1 << 3) != 0 {
            obj.read_max_id = Some(cursor.read_i32::<LittleEndian>().map_err(|_| "read read_max_id")?);
        }
        Ok(obj)
    }
}

#[derive(Debug, Clone, Default)]
